#!/usr/bin/env bash
# Pushes src/ to a Make app with the Make CLI (make-cli), section by section.
# Generated by scripts/generate.js. Not run by the generator: read it first.
#   1. Install and log in to make-cli (see the Make developer docs, Make CLI).
#   2. Create the app once in Make (Create a new app), with the name below.
#   3. APP=privatus-analytics VERSION=1 bash dist/deploy-with-make-cli.sh
